# 【算法思路】按正向最大匹配 (FMM) 算法依据词表切分中文文本，并映射词性词典完成标注。
# 从当前位置按 max_len 递减长度匹配词表，未登录词退化为单字
def fmm_segment(text, vocab, max_len=5):
    tokens = []
    i = 0
    while i < len(text):
        matched = False
        for L in range(min(max_len, len(text)-i), 0, -1):
            if text[i:i+L] in vocab:
                tokens.append(text[i:i+L])
                i += L
                matched = True
                break
        if not matched:
            tokens.append(text[i])
            i += 1
    return tokens
# 查表为每个分词赋予词性标签（缺省为 UNK）
def pos_tag(tokens, pos_dict):
    return [{'word': t, 'pos': pos_dict.get(t, 'UNK')} for t in tokens]

# 【算法思路】统计词频 TF 与平滑逆文档频率 IDF 计算 TF-IDF 权重，按余弦加和排序文档。
import math
# 计算词项在单篇文档中的相对出现频率
def tf(term, doc):
    return doc.count(term)/len(doc) if doc else 0
# 按加一平滑公式统计词项区分度权重
def idf(term, docs):
    n = sum(1 for d in docs if term in d)
    return math.log((len(docs)+1)/(n+1))+1
# 计算 TF 与 IDF 乘积权重
def tfidf(term, doc, docs):
    return round(tf(term,doc)*idf(term,docs),4)
# 累加查询词 TF-IDF 得分并返回最相关 top_k 文档索引
def search(query, docs, top_k=2):
    scores = []
    for i, doc in enumerate(docs):
        score = sum(tfidf(w,doc,docs) for w in query.split())
        scores.append((i, round(score,4)))
    scores.sort(key=lambda x:-x[1])
    return scores[:top_k]

# 【算法思路】构造掩码语言模型 (MLM) 随机掩码样本及忽略索引 -100 标签，并计算预测交叉熵损失。
import numpy as np

# 依概率替换目标 token 为 mask_id 并记录非掩码位置为 -100
def mask_tokens(tokens, mask_id, mask_prob=0.15):
    masked = list(tokens)
    labels = [-100] * len(tokens)
    for i in range(len(tokens)):
        if mask_prob >= 1.0 or (mask_prob > 0.0 and np.random.random() < mask_prob):
            labels[i] = tokens[i]
            masked[i] = mask_id
    return {"masked": masked, "labels": labels}

# 跳过负标签位仅对被掩码位置求解平均交叉熵
def mlm_loss(logits, target_ids):
    logits = np.asarray(logits, dtype=float)
    loss, n = 0.0, 0
    for logit, tid in zip(logits, target_ids):
        if tid < 0:
            continue
        exp = np.exp(logit - np.max(logit))
        probs = exp / np.sum(exp)
        loss += -float(np.log(probs[tid] + 1e-10))
        n += 1
    return round(float(loss / n), 4) if n else 0.0

