# 【算法思路】统计字符级词表中相邻符号对共现频率并反复合并最高频对构建 BPE 子词切分。
import re
# 累加各单词中相邻符号对频次
def get_stats(vocab):
  pairs={}
  for word,tokens in vocab.items():
    for i in range(len(tokens)-1):
      pair=(tokens[i],tokens[i+1])
      pairs[pair]=pairs.get(pair,0)+len(tokens)
  return pairs
# 将指定最高频相邻符号对替换合并为单个符号
def merge_vocab(pair,vocab):
  new={}
  for word,tokens in vocab.items():
    nt=[];i=0
    while i<len(tokens):
      if i<len(tokens)-1 and (tokens[i],tokens[i+1])==pair:
        nt.append(tokens[i]+tokens[i+1]);i+=2
      else:nt.append(tokens[i]);i+=1
    new[word]=nt
  return new
# 执行 n 轮高频对合并后返回切分列表
def bpe_tokenize(word,merges,n):
  vocab={word:list(word)}
  for _ in range(n):
    p=get_stats(vocab)
    if not p:break
    best=max(p,key=p.get)
    vocab=merge_vocab(best,vocab)
  return vocab[word]

# 【算法思路】根据中心词嵌入矩阵内积输出上下文词表 Softmax 分布并计算负对数似然损失。
import numpy as np

# 对数几率稳定归一化为概率分布
def softmax(z):
    z = np.asarray(z, dtype=float)
    zs = z - np.max(z, axis=-1, keepdims=True)
    e = np.exp(zs)
    return e / np.sum(e, axis=-1, keepdims=True)

# 提取中心词向量与输出词矩阵相乘并归一化
def skipgram_forward(center, W_in, W_out):
    W_in, W_out = np.asarray(W_in, dtype=float), np.asarray(W_out, dtype=float)
    return softmax(W_in[center] @ W_out.T)

# 提取目标上下词位置的负对数似然
def skipgram_loss(probs, target):
    probs = np.asarray(probs, dtype=float)
    return float(-np.log(probs[target] + 1e-10))

# 【算法思路】同时实现带掩码过滤的 MLM 损失与判断句对衔接关系的 NSP 二分类交叉熵损失。
import numpy as np

# 二维 logits 批量交叉熵计算
def ce(logits, target):
    logits = np.atleast_2d(np.asarray(logits, dtype=float))
    target = np.asarray(target, dtype=int)
    s = logits - np.max(logits, axis=-1, keepdims=True)
    p = np.exp(s) / np.sum(np.exp(s), axis=-1, keepdims=True)
    return -np.log(p[range(len(target)), target] + 1e-10)

# 按掩码向量加权平均被遮挡位置的交叉熵
def mlm_loss(logits, target_ids, mask):
    mask = np.asarray(mask)
    logits = np.asarray(logits, dtype=float)
    total = 0.0
    cnt = int(np.sum(mask))
    for i in range(len(mask)):
        if mask[i]:
            total += float(ce(logits[i], [target_ids[i]])[0])
    return round(float(total / cnt), 4) if cnt else 0.0

# 直接求下一句预测二分类序列均值损失
def nsp_loss(seq_logits, is_next):
    return round(float(np.mean(ce(seq_logits, is_next))), 4)

